# WinUNLOCKED 0.1beta "Have freedom" — Windows 11 customisation
# 
#
# Generated by DistroForge Studio. Applies your branding, locale and privacy
# baseline to an existing Windows install — it does not compile a Windows ISO.
#
# Run in an elevated PowerShell:
#   powershell -ExecutionPolicy Bypass -File build-WinUNLOCKED.ps1

$ErrorActionPreference = "Stop"
$Root = Join-Path $env:ProgramData "WinUNLOCKED"
New-Item -ItemType Directory -Force -Path $Root | Out-Null

Set-Content -Path (Join-Path $Root "recipe.json") -Value @'
{
  "name": "WinUNLOCKED",
  "codename": "Have freedom",
  "version": "0.1beta",
  "tagline": "",
  "asciiArt": "Win unlocked xx86_64",
  "base": "windows11",
  "arch": "x86_64",
  "kernel": "default",
  "installer": "gui",
  "desktop": "kde",
  "splash": "bgrt",
  "customSplash": "",
  "apps": [
    "chromium"
  ],
  "hostname": "winunlocked",
  "username": "wu11",
  "fullName": "Windows unlocked",
  "locale": "en_GB.UTF-8",
  "keyboard": "gb",
  "timezone": "Europe/London",
  "filesystem": "btrfs",
  "partitioning": "snapshots",
  "bootloader": "grub2",
  "network": "dhcp",
  "services": [
    "NetworkManager",
    "firewalld",
    "chronyd"
  ],
  "kernelCmdline": "quiet splash vt.global_cursor_default=0",
  "repos": [
    "oss",
    "packman"
  ],
  "autologin": false,
  "encryptedHome": false,
  "telemetry": false
}
'@ -Encoding UTF8

Set-Content -Path (Join-Path $Root "boot.txt") -Value @'
Win unlocked xx86_64
'@ -Encoding UTF8

Write-Host "==> Applying WinUNLOCKED identity"
Rename-Computer -NewName "winunlocked" -Force
Set-TimeZone -Id "Europe/London"
Set-WinUserLanguageList -LanguageList "en-GB" -Force

Write-Host "==> Privacy baseline"
New-Item -Force -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" | Out-Null
Set-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name "AllowTelemetry" -Value 0 -Type DWord
Stop-Service -Name DiagTrack -Force -ErrorAction SilentlyContinue
Set-Service -Name DiagTrack -StartupType Disabled -ErrorAction SilentlyContinue

Write-Host ""
Write-Host "==> Done: WinUNLOCKED 0.1beta (Windows 11)"
Write-Host "    Recipe:  $Root\recipe.json"
Write-Host "    Reboot to apply the computer name."
